package com.yskj.shopify.web.controller;
import com.alibaba.fastjson.JSONObject;import com.yskj.dao.dto.org.LoginedUser;import com.yskj.shopify.web.service.CustomStoreConnectionClient;import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpSession;import org.springframework.web.server.ResponseStatusException;import org.springframework.web.servlet.mvc.support.RedirectAttributesModelMap;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class CustomStoreConnectionControllerTest {
 MockHttpSession session(){var session=new MockHttpSession();var u=new LoginedUser();u.setId("server-user");u.setDomainid("domain");u.setAclNameList("[营销管理端访问]||[店铺治理]");session.setAttribute("logineduser",u);return session;}
 JSONObject ready(){var v=new JSONObject();v.put("available",true);v.put("featureEnabled",true);v.put("canTest",true);return v;}
 @Test void unauthenticatedNeverCallsRemote(){var c=mock(CustomStoreConnectionClient.class);assertThatThrownBy(()->new CustomStoreConnectionController(c).probe("custom.example",0,new MockHttpSession(),new RedirectAttributesModelMap())).isInstanceOf(ResponseStatusException.class);verifyNoInteractions(c);}
 @Test void disabledAndReadonlyCannotMutate(){for(String field:new String[]{"featureEnabled","canTest"}){var c=mock(CustomStoreConnectionClient.class);var value=ready();value.put(field,false);when(c.status(any(),anyString())).thenReturn(value);assertThatThrownBy(()->new CustomStoreConnectionController(c).probe("custom.example",0,session(),new RedirectAttributesModelMap())).isInstanceOf(ResponseStatusException.class);verify(c,never()).probe(any(),anyString(),anyLong());}}
 @Test void evenValidCsrfCannotSaveConfigurationOrConnector(){var c=mock(CustomStoreConnectionClient.class);var controller=new CustomStoreConnectionController(c);var session=session();String csrf=CustomStoreConnectionController.csrf(session);assertThatThrownBy(()->controller.saveRequest("custom.example","u","s","e","secret",0,csrf,session,new RedirectAttributesModelMap())).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->controller.sourceRequest("custom.example","CUSTOM","AUW_V2",0,csrf,session,new RedirectAttributesModelMap())).isInstanceOf(ResponseStatusException.class);verifyNoInteractions(c);}
 @Test void failedProbeNeverClaimsSuccess(){var c=mock(CustomStoreConnectionClient.class);when(c.status(any(),anyString())).thenReturn(ready());var failed=new JSONObject();failed.put("state","FAILED");when(c.probe(any(),anyString(),anyLong())).thenReturn(failed);var flash=new RedirectAttributesModelMap();new CustomStoreConnectionController(c).probe("custom.example",0,session(),flash);assertThat(flash.getFlashAttributes()).containsKey("errorMessage").doesNotContainKey("successMessage");verify(c).probe(argThat(u->u.getId().equals("server-user")),eq("custom.example"),eq(0L));}
 @Test void requestMappingsRejectMissingAndWrongCsrfBeforeMutations(){var c=mock(CustomStoreConnectionClient.class);var controller=new CustomStoreConnectionController(c);var session=session();String token=CustomStoreConnectionController.csrf(session);for(String bad:new String[]{null,"wrong"})assertThatThrownBy(()->controller.probeRequest("custom.example",0,bad,session,new RedirectAttributesModelMap())).isInstanceOf(ResponseStatusException.class);verifyNoInteractions(c);assertThat(token).isEqualTo(CustomStoreConnectionController.csrf(session));}
 @Test void sourceSelectionRejectsCsrfAndReadonly(){var c=mock(CustomStoreConnectionClient.class);var controller=new CustomStoreConnectionController(c);var session=session();var flash=new RedirectAttributesModelMap();assertThatThrownBy(()->controller.sourceRequest("custom.example","CUSTOM","AUW_V2",0,"wrong",session,flash)).isInstanceOf(ResponseStatusException.class);verifyNoInteractions(c);var p=new JSONObject();p.put("available",true);p.put("selectionAvailable",true);p.put("canSelect",false);when(c.sourceProfile(any(),anyString())).thenReturn(p);String csrf=CustomStoreConnectionController.csrf(session);assertThatThrownBy(()->controller.sourceRequest("custom.example","CUSTOM","AUW_V2",0,csrf,session,flash)).isInstanceOf(ResponseStatusException.class);verify(c,never()).saveSourceProfile(any(),anyString(),anyString(),anyString(),anyLong());}
 @Test void oldPageRedirectsToInlineCardWithoutConfigurationLookup(){var c=mock(CustomStoreConnectionClient.class);assertThat(new CustomStoreConnectionController(c).page("custom.example",session(),new org.springframework.ui.ExtendedModelMap())).isEqualTo("redirect:/stores?shop=custom.example#store-data-connection");verifyNoInteractions(c);}
 @Test void allowedProbeReturnsToInlineStoreCard(){var c=mock(CustomStoreConnectionClient.class);when(c.status(any(),anyString())).thenReturn(ready());var result=new JSONObject();result.put("state","VERIFIED");when(c.probe(any(),anyString(),anyLong())).thenReturn(result);var flash=new RedirectAttributesModelMap();assertThat(new CustomStoreConnectionController(c).probe("custom.example",1,session(),flash)).isEqualTo("redirect:/stores?shop=custom.example#store-data-connection");assertThat(flash.getFlashAttributes()).containsKey("successMessage");verify(c).probe(any(),eq("custom.example"),eq(1L));}
}
